-- Generated by `engine types sync` from types/*.toml (sqlite).
-- index published `article`; index published `author`

CREATE INDEX IF NOT EXISTS content_article_published_newest ON content_article ((COALESCE(published_at, created_at)) DESC, id DESC) WHERE status = 'published';

CREATE INDEX IF NOT EXISTS content_author_published_newest ON content_author ((COALESCE(published_at, created_at)) DESC, id DESC) WHERE status = 'published';
